-- Políticas de acompanhamento — EXEMPLOS de demonstração (ids determinísticos de00…, idempotente por `not exists`).
--
-- Os tipos abaixo são DADOS de exemplo (observar, orientar, treinar, plano de ação, encaminhar à liderança, investigar,
-- reconhecer, solicitar avaliação de continuidade) — nunca um enum do produto nem uma escada obrigatória: o administrador
-- edita, inativa ou cria outros pela tela. As duas políticas nascem em RASCUNHO: nada é avaliado até alguém validar e publicar.
-- Só entram por `npm run db:seed:demo` (recusado em produção); a migration 131 não cria nenhum tipo de negócio.

insert into intervention_types (id, organization_id, key)
select v.id::uuid, '00000000-0000-4000-8000-000000000001', v.key
from (values
  ('de00a1e0-0000-4000-8000-000000000001', 'OBSERVAR'),
  ('de00a1e0-0000-4000-8000-000000000002', 'ORIENTAR'),
  ('de00a1e0-0000-4000-8000-000000000003', 'TREINAR'),
  ('de00a1e0-0000-4000-8000-000000000004', 'PLANO_DE_ACAO'),
  ('de00a1e0-0000-4000-8000-000000000005', 'REVISAO_LIDERANCA'),
  ('de00a1e0-0000-4000-8000-000000000006', 'INVESTIGAR_CAUSA'),
  ('de00a1e0-0000-4000-8000-000000000007', 'RECONHECER'),
  ('de00a1e0-0000-4000-8000-000000000008', 'AVALIACAO_CONTINUIDADE')
) v(id, key)
where exists (select 1 from organizations where id = '00000000-0000-4000-8000-000000000001')
  and not exists (select 1 from intervention_types t where t.organization_id = '00000000-0000-4000-8000-000000000001' and t.key = v.key);

insert into intervention_type_versions (id, organization_id, type_id, version, status, definition, published_at)
select v.id::uuid, '00000000-0000-4000-8000-000000000001', t.id, 1, 'PUBLISHED', v.definition::jsonb, now()
from (values
  ('de00a1e1-0000-4000-8000-000000000001', 'OBSERVAR', $j${"schemaVersion":"INTERVENTION_TYPE_V1","name":"Observar","description":"Acompanhar de perto, sem cobrança, por um período curto — quando o sinal ainda não sustenta outra ação.","capabilities":["OBSERVATION","CHECKPOINTS"],"responsibleRole":"SUPERVISOR","defaultDueDays":15,"approval":{"required":false},"evidence":{"minimumItems":1,"acceptedKinds":["EVALUATION","INDICATOR_RESULT","FEEDBACK"]},"form":[],"completion":{"requireAllTasksDone":false,"requireLearningAssessment":false,"requireOperationalReading":false,"requireOutcomeNote":true},"incompatibleWith":[],"aiDraft":false}$j$),
  ('de00a1e1-0000-4000-8000-000000000002', 'ORIENTAR', $j${"schemaVersion":"INTERVENTION_TYPE_V1","name":"Orientar","description":"Conversa de orientação com o colaborador sobre o procedimento ou o resultado, registrada.","capabilities":["GUIDANCE"],"responsibleRole":"SUPERVISOR","defaultDueDays":7,"approval":{"required":false},"evidence":{"minimumItems":1,"acceptedKinds":["EVALUATION","INDICATOR_RESULT","FEEDBACK","DIAGNOSIS"]},"form":[{"key":"conversaEm","label":"Data da conversa","kind":"DATE","required":true}],"completion":{"requireAllTasksDone":false,"requireLearningAssessment":false,"requireOperationalReading":false,"requireOutcomeNote":true},"incompatibleWith":[],"aiDraft":false}$j$),
  ('de00a1e1-0000-4000-8000-000000000003', 'TREINAR', $j${"schemaVersion":"INTERVENTION_TYPE_V1","name":"Treinar","description":"Trilha de treinamento ligada a uma competência diagnosticada: conteúdos aprovados, atividades e avaliação de aprendizagem.","capabilities":["TRAINING","TASKS"],"responsibleRole":"SUPERVISOR","defaultDueDays":30,"approval":{"required":true,"approverRole":"COORDINATOR"},"evidence":{"minimumItems":1,"acceptedKinds":["EVALUATION","DIAGNOSIS","FEEDBACK"]},"form":[],"completion":{"requireAllTasksDone":true,"requireLearningAssessment":true,"requireOperationalReading":true,"requireOutcomeNote":true},"incompatibleWith":["RECONHECER"],"aiDraft":true}$j$),
  ('de00a1e1-0000-4000-8000-000000000004', 'PLANO_DE_ACAO', $j${"schemaVersion":"INTERVENTION_TYPE_V1","name":"Plano de ação","description":"Plano com situação inicial, objetivo mensurável, tarefas, apoio, checkpoints e critério de encerramento.","capabilities":["ACTION_PLAN"],"responsibleRole":"SUPERVISOR","defaultDueDays":30,"approval":{"required":true,"approverRole":"MANAGER"},"evidence":{"minimumItems":1,"acceptedKinds":["EVALUATION","INDICATOR_RESULT","DIAGNOSIS","FEEDBACK"]},"form":[],"completion":{"requireAllTasksDone":true,"requireLearningAssessment":false,"requireOperationalReading":true,"requireOutcomeNote":true},"incompatibleWith":["RECONHECER"],"aiDraft":true}$j$),
  ('de00a1e1-0000-4000-8000-000000000005', 'REVISAO_LIDERANCA', $j${"schemaVersion":"INTERVENTION_TYPE_V1","name":"Encaminhar à liderança","description":"A liderança acima do supervisor analisa o caso e registra um parecer.","capabilities":["LEADERSHIP_REVIEW"],"responsibleRole":"MANAGER","defaultDueDays":10,"approval":{"required":false},"evidence":{"minimumItems":1,"acceptedKinds":["EVALUATION","INDICATOR_RESULT","DIAGNOSIS","FEEDBACK"]},"form":[],"completion":{"requireAllTasksDone":false,"requireLearningAssessment":false,"requireOperationalReading":false,"requireOutcomeNote":true},"incompatibleWith":[],"aiDraft":false}$j$),
  ('de00a1e1-0000-4000-8000-000000000006', 'INVESTIGAR_CAUSA', $j${"schemaVersion":"INTERVENTION_TYPE_V1","name":"Investigar causa e dados","description":"Antes de qualquer conclusão: verificar dados faltantes/inconsistentes ou investigar a causa quando não há diagnóstico sustentado.","capabilities":["DATA_REVIEW"],"responsibleRole":"SUPERVISOR","defaultDueDays":5,"approval":{"required":false},"evidence":{"minimumItems":1,"acceptedKinds":["EVALUATION"]},"form":[],"completion":{"requireAllTasksDone":false,"requireLearningAssessment":false,"requireOperationalReading":false,"requireOutcomeNote":true},"incompatibleWith":[],"aiDraft":false}$j$),
  ('de00a1e1-0000-4000-8000-000000000007', 'RECONHECER', $j${"schemaVersion":"INTERVENTION_TYPE_V1","name":"Reconhecer resultado","description":"Elogio ou reconhecimento de um bom resultado oficial.","capabilities":["RECOGNITION"],"responsibleRole":"SUPERVISOR","defaultDueDays":7,"approval":{"required":false},"evidence":{"minimumItems":1,"acceptedKinds":["EVALUATION","INDICATOR_RESULT"]},"form":[],"completion":{"requireAllTasksDone":false,"requireLearningAssessment":false,"requireOperationalReading":false,"requireOutcomeNote":true},"incompatibleWith":["TREINAR","PLANO_DE_ACAO"],"aiDraft":false}$j$),
  ('de00a1e1-0000-4000-8000-000000000008', 'AVALIACAO_CONTINUIDADE', $j${"schemaVersion":"INTERVENTION_TYPE_V1","name":"Solicitar avaliação de continuidade","description":"Pede a uma pessoa autorizada que avalie a continuidade, com o fundamento organizado. A INIA nunca decide, aprova ou altera a situação funcional.","capabilities":["CONTINUITY_REVIEW"],"responsibleRole":"MANAGER","defaultDueDays":10,"approval":{"required":true,"approverRole":"SENIOR_MANAGER"},"evidence":{"minimumItems":2,"acceptedKinds":["EVALUATION","INDICATOR_RESULT","DIAGNOSIS","FEEDBACK"]},"form":[],"completion":{"requireAllTasksDone":false,"requireLearningAssessment":false,"requireOperationalReading":false,"requireOutcomeNote":false},"incompatibleWith":[],"aiDraft":false}$j$)
) v(id, key, definition)
join intervention_types t on t.organization_id = '00000000-0000-4000-8000-000000000001' and t.key = v.key
where not exists (select 1 from intervention_type_versions x where x.type_id = t.id);

insert into competencies (id, organization_id, key, name, description, indicator_codes, activities)
select 'de00a1e2-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000001', 'GESTAO_DO_TEMPO_DE_ATENDIMENTO', 'Gestão do tempo de atendimento',
       'Conduzir o atendimento sem esperas desnecessárias: avisar e justificar consultas, informar prazos e encerrar com confirmação. Vincule as práticas do diagnóstico e os documentos publicados na tela.',
       array(select code from indicator_definitions where organization_id = '00000000-0000-4000-8000-000000000001' and code = 'TMA'),
       $j$[{"key":"estudo-procedimento","title":"Estudar o procedimento de espera e consulta","description":"Ler o procedimento vigente e anotar as dúvidas para a conversa com o supervisor.","kind":"STUDY","documentId":null,"estimatedMinutes":30},{"key":"escuta-chamadas","title":"Ouvir duas chamadas de referência","description":"Acompanhar com o supervisor duas chamadas em que a consulta foi bem conduzida.","kind":"SHADOWING","documentId":null,"estimatedMinutes":40}]$j$::jsonb
where exists (select 1 from organizations where id = '00000000-0000-4000-8000-000000000001')
  and not exists (select 1 from competencies where organization_id = '00000000-0000-4000-8000-000000000001' and key = 'GESTAO_DO_TEMPO_DE_ATENDIMENTO');

insert into intervention_policies (id, organization_id, key, name, scope_type)
select v.id::uuid, '00000000-0000-4000-8000-000000000001', v.key, v.name, 'ORGANIZATION'
from (values
  ('de00a1e3-0000-4000-8000-000000000001', 'ACOMPANHAMENTO_TMA_EXEMPLO', 'Acompanhamento de TMA (exemplo)'),
  ('de00a1e3-0000-4000-8000-000000000002', 'AVALIACAO_CONTINUIDADE_EXEMPLO', 'Avaliação de continuidade (exemplo)')
) v(id, key, name)
where exists (select 1 from organizations where id = '00000000-0000-4000-8000-000000000001')
  and not exists (select 1 from intervention_policies p where p.organization_id = '00000000-0000-4000-8000-000000000001' and p.key = v.key);

insert into intervention_policy_versions (id, organization_id, policy_id, version, status, definition)
select v.id::uuid, '00000000-0000-4000-8000-000000000001', p.id, 1, 'DRAFT', v.definition::jsonb
from (values
  ('de00a1e4-0000-4000-8000-000000000001', 'ACOMPANHAMENTO_TMA_EXEMPLO', $j${"schemaVersion":"INTERVENTION_POLICY_V1","description":"Exemplo: do sinal ao plano, sem escada fixa — cada regra declara condições e ações; a primeira atendida por prioridade decide.","indicatorCode":"TMA","matchStrategy":"FIRST_MATCH","report":{"aiNarrative":false},"rules":[
    {"key":"PLANO_SEM_EVOLUCAO","name":"Plano concluído sem evolução e Q4 persistente","priority":1,"justification":"Um plano de ação já foi concluído sem melhora operacional e o resultado oficial segue no pior quartil: a liderança precisa analisar o caso.","when":{"operator":"ALL","items":[{"kind":"PRIOR_INTERVENTIONS","typeKeys":["PLANO_DE_ACAO"],"statuses":["COMPLETED"],"operationalResults":["UNCHANGED","WORSENED"],"sameSubject":true,"withinDays":120,"comparator":"GTE","threshold":1},{"kind":"INDICATOR","criterion":{"comparator":"GTE","thresholdNumeric":2,"performanceQuery":{"kind":"EMPLOYEE_PERFORMANCE","metric":"INDICATOR_QUARTILE","indicatorCode":"TMA","recurrence":{"periods":2,"matchQuartile":"Q4"}}}}]},"actions":[{"typeKey":"REVISAO_LIDERANCA","effect":"OPEN","dueInDays":null,"onActive":"UPDATE","cooldownDays":30}],"inconclusiveActions":[]},
    {"key":"Q4_COM_DIAGNOSTICO","name":"Q4 oficial recorrente com diagnóstico sustentado","priority":2,"justification":"Pior quartil oficial em dois fechamentos e um diagnóstico sustentado que aponta a causa: cabe treinar e abrir um plano.","when":{"operator":"ALL","items":[{"kind":"INDICATOR","criterion":{"comparator":"GTE","thresholdNumeric":2,"performanceQuery":{"kind":"EMPLOYEE_PERFORMANCE","metric":"INDICATOR_QUARTILE","indicatorCode":"TMA","recurrence":{"periods":2,"matchQuartile":"Q4"}}}},{"kind":"SUPPORTED_DIAGNOSIS","indicatorCode":null,"competencyKeys":[],"withinDays":90,"expectation":"EXISTS"}]},"actions":[{"typeKey":"TREINAR","effect":"RECOMMEND","dueInDays":null,"onActive":"KEEP","cooldownDays":45},{"typeKey":"PLANO_DE_ACAO","effect":"OPEN","dueInDays":30,"onActive":"UPDATE","cooldownDays":30}],"inconclusiveActions":[{"typeKey":"INVESTIGAR_CAUSA","effect":"OPEN","dueInDays":null,"onActive":"KEEP","cooldownDays":0}]},
    {"key":"Q4_SEM_DIAGNOSTICO","name":"Q4 oficial recorrente sem diagnóstico","priority":3,"justification":"Resultado oficial no pior quartil sem diagnóstico sustentado: investigar a causa antes de definir treinamento.","when":{"operator":"ALL","items":[{"kind":"INDICATOR","criterion":{"comparator":"GTE","thresholdNumeric":2,"performanceQuery":{"kind":"EMPLOYEE_PERFORMANCE","metric":"INDICATOR_QUARTILE","indicatorCode":"TMA","recurrence":{"periods":2,"matchQuartile":"Q4"}}}},{"kind":"SUPPORTED_DIAGNOSIS","indicatorCode":null,"competencyKeys":[],"withinDays":90,"expectation":"NOT_EXISTS"}]},"actions":[{"typeKey":"INVESTIGAR_CAUSA","effect":"OPEN","dueInDays":null,"onActive":"KEEP","cooldownDays":15},{"typeKey":"ORIENTAR","effect":"RECOMMEND","dueInDays":null,"onActive":"KEEP","cooldownDays":15}],"inconclusiveActions":[{"typeKey":"INVESTIGAR_CAUSA","effect":"OPEN","dueInDays":null,"onActive":"KEEP","cooldownDays":0}]},
    {"key":"ACIMA_DA_META_30D","name":"TMA acima da meta nos últimos 30 dias","priority":4,"justification":"Medição diária acima da meta vigente na janela de 30 dias, com cobertura suficiente: observar e orientar.","when":{"operator":"ALL","items":[{"kind":"INDICATOR","criterion":{"comparator":"GT","historicalQuery":{"kind":"INDICATOR_THRESHOLD_COUNT","indicatorCode":"TMA","source":"MEASUREMENT","aggregation":"WEIGHTED_AVERAGE","period":{"kind":"ROLLING_DAYS","days":30},"minimumCoverage":0.6,"compareTo":{"kind":"GOAL"}}}},{"kind":"EMPLOYMENT","check":"CURRENTLY_ELIGIBLE","expected":true}]},"actions":[{"typeKey":"OBSERVAR","effect":"OPEN","dueInDays":15,"onActive":"KEEP","cooldownDays":15},{"typeKey":"ORIENTAR","effect":"RECOMMEND","dueInDays":null,"onActive":"KEEP","cooldownDays":15}],"inconclusiveActions":[{"typeKey":"INVESTIGAR_CAUSA","effect":"OPEN","dueInDays":null,"onActive":"KEEP","cooldownDays":7}]},
    {"key":"Q1_RECONHECER","name":"Q1 oficial no último fechamento","priority":5,"justification":"Melhor quartil oficial no último fechamento: reconhecer o resultado.","when":{"operator":"ALL","items":[{"kind":"INDICATOR","criterion":{"comparator":"EQUALS","thresholdText":"Q1","performanceQuery":{"kind":"EMPLOYEE_PERFORMANCE","metric":"INDICATOR_QUARTILE","indicatorCode":"TMA"}}}]},"actions":[{"typeKey":"RECONHECER","effect":"RECOMMEND","dueInDays":null,"onActive":"KEEP","cooldownDays":60}],"inconclusiveActions":[]}
  ]}$j$),
  ('de00a1e4-0000-4000-8000-000000000002', 'AVALIACAO_CONTINUIDADE_EXEMPLO', $j${"schemaVersion":"INTERVENTION_POLICY_V1","description":"Exemplo restrito: organiza o fundamento e SOLICITA uma decisão humana. Nunca decide, aprova automaticamente ou altera a situação funcional.","indicatorCode":"TMA","matchStrategy":"FIRST_MATCH","report":{"aiNarrative":false},"rules":[
    {"key":"PLANOS_SEM_EVOLUCAO","name":"Dois planos concluídos sem evolução e Q4 oficial persistente","priority":1,"justification":"Dois planos de ação concluídos nos últimos 180 dias sem melhora operacional e pior quartil oficial em três fechamentos seguidos: solicitar avaliação de continuidade a quem tem a permissão de decidir.","when":{"operator":"ALL","items":[{"kind":"PRIOR_INTERVENTIONS","typeKeys":["PLANO_DE_ACAO"],"statuses":["COMPLETED"],"operationalResults":["UNCHANGED","WORSENED"],"sameSubject":true,"withinDays":180,"comparator":"GTE","threshold":2},{"kind":"INDICATOR","criterion":{"comparator":"GTE","thresholdNumeric":3,"performanceQuery":{"kind":"EMPLOYEE_PERFORMANCE","metric":"INDICATOR_QUARTILE","indicatorCode":"TMA","recurrence":{"periods":3,"matchQuartile":"Q4"}}}},{"kind":"EMPLOYMENT","check":"CURRENTLY_ELIGIBLE","expected":true}]},"actions":[{"typeKey":"AVALIACAO_CONTINUIDADE","effect":"OPEN","dueInDays":null,"onActive":"KEEP","cooldownDays":90}],"inconclusiveActions":[]}
  ]}$j$)
) v(id, key, definition)
join intervention_policies p on p.organization_id = '00000000-0000-4000-8000-000000000001' and p.key = v.key
where not exists (select 1 from intervention_policy_versions x where x.policy_id = p.id);
